28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    @Email
63	    private String email;
64	
65	    @Column(name = "postcode")
66	    private String postcode;
67	
68	    @Column(name = "customer_code")
69	    private String customerCode;
70	
71	    @Column(name = "registration_date")
72	    private LocalDate registrationDate;
73	
74	    @Column(name = "birth_date")
75	    private LocalDate birthDate;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @Column(name = "deleted", nullable = false)
90	    private boolean deleted;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    public String getTitle() {
96	        return this.title;
97	    }
98	
99	    public void setTitle(String title) {
100	        this.title = title;
101	    }
102	
103	    public String getAddress() {
104	        return this.address;
105	    }
106	
107	    public void setAddress(String address) {
108	        this.address = address;
109	    }
110	
111	    public String getAddressLine1() {
112	        return this.addressLine1;
113	    }
114	
115	    public void setAddressLine1(String addressLine1) {
116	        this.addressLine1 = addressLine1;
117	    }
118	
119	    public String getAddressLine2() {
120	        return this.addressLine2;
121	    }
122	
123	    public void setAddressLine2(String addressLine2) {
124	        this.addressLine2 = addressLine2;
125	    }
126	
127	    public String getCity() {
128	        return this.city;
129	    }
130	
131	    public void setCity(String city) {
132	        this.city = city;
133	    }
134	
135	    public String getTelephone() {
136	        return this.telephone;
137	    }
138	
139	    public void setTelephone(String telephone) {
140	        this.telephone = telephone;
141	    }
142	
143	    public String getEmail() {
144	        return this.email;
145	    }
146	
147	    public void setEmail(String email) {
148	        this.email = email;
149	    }
150	
151	    /**
152	     * Whether this owner has a non-blank email address on file.
153	     */
154	    public boolean hasEmail() {
155	        return this.email != null && !this.email.isBlank();
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    public String getCustomerCode() {
167	        return this.customerCode;
168	    }
169	
170	    public void setCustomerCode(String customerCode) {
171	        this.customerCode = customerCode;
172	    }
173	
174	    public LocalDate getRegistrationDate() {
175	        return this.registrationDate;
176	    }
177	
178	    public void setRegistrationDate(LocalDate registrationDate) {
179	        this.registrationDate = registrationDate;
180	    }
181	
182	    /**
183	     * The owner's tenure, in whole fiscal years (starting 1 July) elapsed from its
184	     * registration date's fiscal year up to the fiscal year containing {@code asOf}.
185	     * Returns 0 when the registration date is absent (as for a brand-new owner) or when
186	     * {@code asOf} falls in an earlier fiscal year than the registration date.
187	     */
188	    public long tenureInFiscalYears(LocalDate asOf) {
189	        if (this.registrationDate == null || asOf == null) {
190	            return 0;
191	        }
192	        int elapsed = FiscalYear.containing(this.registrationDate).yearsUntil(FiscalYear.containing(asOf));
193	        return Math.max(0, elapsed);
194	    }
195	
196	    public LocalDate getBirthDate() {
197	        return this.birthDate;
198	    }
199	
200	    public void setBirthDate(LocalDate birthDate) {
201	        this.birthDate = birthDate;
202	    }
203	
204	    public String getHouseholdId() {
205	        return this.householdId;
206	    }
207	
208	    public void setHouseholdId(String householdId) {
209	        this.householdId = householdId;
210	    }
211	
212	    public Integer getNamesakeCount() {
213	        return this.namesakeCount;
214	    }
215	
216	    public void setNamesakeCount(Integer namesakeCount) {
217	        this.namesakeCount = namesakeCount;
218	    }
219	
220	    public Boolean getPossibleDuplicate() {
221	        return this.possibleDuplicate;
222	    }
223	
224	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
225	        this.possibleDuplicate = possibleDuplicate;
226	    }
227	
228	    public Integer getPossibleDuplicateOf() {
229	        return this.possibleDuplicateOf;
230	    }
231	
232	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
233	        this.possibleDuplicateOf = possibleDuplicateOf;
234	    }
235	
236	    /**
237	     * Whether this owner has been soft-deleted. A soft-deleted owner's row is retained and
238	     * still readable, but it is ignored by the duplicate and identity checks that guard owner
239	     * creation. A newly created owner is not deleted.
240	     */
241	    public boolean isDeleted() {
242	        return this.deleted;
243	    }
244	
245	    public void setDeleted(boolean deleted) {
246	        this.deleted = deleted;
247	    }
248	
249	    protected Set<Pet> getPetsInternal() {
250	        if (this.pets == null) {
251	            this.pets = new HashSet<>();
252	        }
253	        return this.pets;
254	    }
255	
256	    protected void setPetsInternal(Set<Pet> pets) {
257	        this.pets = pets;
258	    }
259	
260	    public List<Pet> getPets() {
261	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
262	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
263	        return Collections.unmodifiableList(sortedPets);
264	    }
265	
266	    public void setPets(List<Pet> pets) {
267	        this.pets = new HashSet<>(pets);
268	    }
269	
270	    public void addPet(Pet pet) {
271	        getPetsInternal().add(pet);
272	        pet.setOwner(this);
273	    }
274	
275	    /**
276	     * Return the Pet with the given name, or null if none found for this Owner.
277	     *
278	     * @param name to test
279	     * @return true if pet name is already in use
280	     */
281	    public Pet getPet(String name) {
282	        return getPet(name, false);
283	    }
284	
285	    /**
286	     * Return the Pet with the given name, or null if none found for this Owner.
287	     *
288	     * @param name to test
289	     * @return true if pet name is already in use
290	     */
291	    public Pet getPet(String name, boolean ignoreNew) {
292	        name = name.toLowerCase();
293	        for (Pet pet : getPetsInternal()) {
294	            if (!ignoreNew || !pet.isNew()) {
295	                String compName = pet.getName();
296	                compName = compName.toLowerCase();
297	                if (compName.equals(name)) {
298	                    return pet;
299	                }
300	            }
301	        }
302	        return null;
303	    }
304	
305	    public Pet getPet(Integer petId) {
306	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
307	    }
308	
309	    @Override
310	    public String toString() {
311	        return new ToStringCreator(this)
312	
313	            .append("id", this.getId())
314	            .append("new", this.isNew())
315	            .append("lastName", this.getLastName())
316	            .append("firstName", this.getFirstName())
317	            .append("address", this.address)
318	            .append("city", this.city)
319	            .append("telephone", this.telephone)
320	            .toString();
321	    }
322	}
