17	package org.springframework.samples.petclinic.service;
18	
19	import org.springframework.beans.factory.annotation.Autowired;
20	import org.springframework.samples.petclinic.model.Owner;
21	import org.springframework.stereotype.Component;
22	
23	import java.time.Clock;
24	import java.time.LocalDate;
25	
26	/**
27	 * Scores an owner's membership and maps that score to a numeric level. Points start at 0
28	 * and accrue for each qualifying attribute:
29	 * <ul>
30	 *   <li>+{@value #EMAIL_POINTS} when the owner has an email address on file;</li>
31	 *   <li>+{@value #NO_NAMESAKE_POINTS} when the owner has no namesakes ({@code namesakeCount} is 0);</li>
32	 *   <li>+{@value #LARGE_HOUSEHOLD_POINTS} when the owner's household has {@value #LARGE_HOUSEHOLD_SIZE}
33	 *       or more members;</li>
34	 *   <li>+{@value #TENURE_POINTS} when the owner's tenure exceeds {@value #TENURE_THRESHOLD_FISCAL_YEARS}
35	 *       fiscal year(s).</li>
36	 * </ul>
37	 * The point total maps to a level as 1 (0-1 points), 2 (2-3), 3 (4-5) and 4 (6 or more).
38	 */
39	@Component
40	public class MembershipLevelEvaluator {
41	
42	    /** Points gained when an email address is on file. */
43	    static final int EMAIL_POINTS = 2;
44	
45	    /** Points gained when the owner has no namesakes. */
46	    static final int NO_NAMESAKE_POINTS = 1;
47	
48	    /** Points gained when the owner belongs to a large household. */
49	    static final int LARGE_HOUSEHOLD_POINTS = 2;
50	
51	    /** Points gained when tenure exceeds {@value #TENURE_THRESHOLD_FISCAL_YEARS} fiscal year(s). */
52	    static final int TENURE_POINTS = 3;
53	
54	    /** Household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} apply. */
55	    static final int LARGE_HOUSEHOLD_SIZE = 3;
56	
57	    /** Tenure, in whole fiscal years, that must be exceeded for the tenure points to apply. */
58	    static final long TENURE_THRESHOLD_FISCAL_YEARS = 1;
59	
60	    private final ClinicService clinicService;
61	
62	    private final Clock clock;
63	
64	    @Autowired
65	    public MembershipLevelEvaluator(ClinicService clinicService) {
66	        this(clinicService, Clock.systemDefaultZone());
67	    }
68	
69	    MembershipLevelEvaluator(ClinicService clinicService, Clock clock) {
70	        this.clinicService = clinicService;
71	        this.clock = clock;
72	    }
73	
74	    /**
75	     * @param owner the owner whose membership points are evaluated
76	     * @return the owner's membership points, or {@code null} when the owner is not known
77	     */
78	    public Integer pointsFor(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        int points = 0;
83	        if (owner.hasEmail()) {
84	            points += EMAIL_POINTS;
85	        }
86	        if (hasNoNamesakes(owner)) {
87	            points += NO_NAMESAKE_POINTS;
88	        }
89	        if (hasLargeHousehold(owner)) {
90	            points += LARGE_HOUSEHOLD_POINTS;
91	        }
92	        if (hasQualifyingTenure(owner)) {
93	            points += TENURE_POINTS;
94	        }
95	        return points;
96	    }
97	
98	    /**
99	     * @param owner the owner whose level is evaluated
100	     * @return the owner's membership level, or {@code null} when the owner is not known
101	     */
102	    public Integer levelFor(Owner owner) {
103	        Integer points = pointsFor(owner);
104	        return points == null ? null : levelForPoints(points);
105	    }
106	
107	    /**
108	     * Maps a point total to a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more).
109	     */
110	    private int levelForPoints(int points) {
111	        if (points <= 1) {
112	            return 1;
113	        }
114	        if (points <= 3) {
115	            return 2;
116	        }
117	        if (points <= 5) {
118	            return 3;
119	        }
120	        return 4;
121	    }
122	
123	    private boolean hasNoNamesakes(Owner owner) {
124	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
125	    }
126	
127	    private boolean hasLargeHousehold(Owner owner) {
128	        return owner.getHouseholdId() != null
129	            && clinicService.countOwnersInHousehold(owner.getHouseholdId()) >= LARGE_HOUSEHOLD_SIZE;
130	    }
131	
132	    private boolean hasQualifyingTenure(Owner owner) {
133	        return owner.tenureInFiscalYears(LocalDate.now(clock)) > TENURE_THRESHOLD_FISCAL_YEARS;
134	    }
135	}
