17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.HexFormat;
23	import java.util.List;
24	import java.util.Locale;
25	
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.samples.petclinic.service.ClinicService;
28	import org.springframework.stereotype.Component;
29	
30	/**
31	 * Household identity for owners: two owners belong to the same household when their last name
32	 * (compared case-insensitively, with runs of whitespace collapsed) and postcode match. The
33	 * {@code householdId} is derived deterministically from those two fields, so owners with the
34	 * same last name and postcode share it automatically without any explicit linking. Provides the
35	 * shared lookup and identifier logic reused by the duplicate guard and by the household-size
36	 * queries that key off {@code householdId}.
37	 */
38	@Component
39	public class Households {
40	
41	    /** Number of leading SHA-256 hex characters that make up a household identifier. */
42	    private static final int ID_LENGTH = 12;
43	
44	    private final ClinicService clinicService;
45	
46	    public Households(ClinicService clinicService) {
47	        this.clinicService = clinicService;
48	    }
49	
50	    /**
51	     * Existing owners that share {@code candidate}'s household (same {@link #householdId(Owner)
52	     * household identifier}). Intended for a not-yet-persisted candidate, so the candidate never
53	     * appears in the result. Soft-deleted owners are excluded: they no longer count as household
54	     * members for duplicate detection.
55	     */
56	    public List<Owner> findMembers(Owner candidate) {
57	        String householdId = householdId(candidate);
58	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
59	            .filter(existing -> !existing.isDeleted())
60	            .filter(existing -> householdId.equals(householdId(existing)))
61	            .toList();
62	    }
63	
64	    /**
65	     * The stable identifier every owner in {@code owner}'s household shares: the first
66	     * {@value #ID_LENGTH} hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
67	     * The same last name and postcode always yield the same id.
68	     */
69	    public String householdId(Owner owner) {
70	        String key = normalize(owner.getLastName()) + "|" + segment(owner.getPostcode());
71	        return sha256Hex(key).substring(0, ID_LENGTH);
72	    }
73	
74	    /**
75	     * Canonicalize the last name for household comparison: {@code null} becomes empty, surrounding
76	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the result
77	     * is lower-cased.
78	     */
79	    private String normalize(String value) {
80	        if (value == null) {
81	            return "";
82	        }
83	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
84	    }
85	
86	    private String segment(String value) {
87	        return value == null ? "" : value;
88	    }
89	
90	    private String sha256Hex(String value) {
91	        try {
92	            byte[] digest = MessageDigest.getInstance("SHA-256")
93	                .digest(value.getBytes(StandardCharsets.UTF_8));
94	            return HexFormat.of().formatHex(digest);
95	        }
96	        catch (NoSuchAlgorithmException e) {
97	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
98	        }
99	    }
100	}
