186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
189	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
190	        if (replay != null) {
191	            return replay;
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
195	        addressResolver.resolve(owner);
196	        registrationDateValidator.validate(owner.getRegistrationDate());
197	        LocalDate registrationDate = owner.getRegistrationDate() != null
198	            ? owner.getRegistrationDate() : LocalDate.now();
199	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
200	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
201	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
202	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
203	        cityCapacityValidator.validate(owner);
204	        owner.setHouseholdId(households.householdId(owner));
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        householdDuplicateValidator.validate(owner, sharesHousehold);
207	        if (sharesHousehold) {
208	            // A declared household member is not a suspected duplicate.
209	            owner.setPossibleDuplicate(false);
210	        } else {
211	            possibleDuplicateDetector.detect(owner);
212	        }
213	        this.clinicService.saveOwner(owner);
214	        ownerAuditLogger.logCreated(owner);
215	        ownerIdempotencyStore.record(idempotencyKey, owner.getId());
216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
220	    }
