222	    /**
223	     * If {@code idempotencyKey} has already been used to create an owner that still exists, returns
224	     * that originally created owner with 200 so the repeated create is a no-op; otherwise returns
225	     * {@code null} to let the create proceed normally.
226	     */
227	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
228	        return ownerIdempotencyStore.find(idempotencyKey)
229	            .map(this.clinicService::findOwnerById)
230	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
231	            .orElse(null);
232	    }
