18	/**
19	 * Formats an owner's membership number as {@code "<customerCode>-M<YY>"}, where
20	 * {@code YY} is the last two digits of the fiscal year (starting 1 July) that contains the
21	 * business-day-adjusted registration date (e.g. {@code "NSW-A1B2C3D4-M26"}). The number is
22	 * undefined until both the customer code and registration date have been assigned.
23	 */
24	public final class MembershipNumber {
25	
26	    private MembershipNumber() {
27	    }
28	
29	    /**
30	     * Returns the formatted membership number for the owner, or {@code null} when the owner
31	     * is {@code null} or its customer code or registration date has not been assigned yet.
32	     */
33	    public static String forOwner(Owner owner) {
34	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
35	            return null;
36	        }
37	        int fiscalYear = FiscalYear.containing(owner.getRegistrationDate()).shortYear();
38	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear);
39	    }
